// Generated by `manage.py bazis_front e2e` from the scenario `viewer-only-reads` of spec/product.yaml:
// never edit it, change the specs and generate it again.

import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('viewer-only-reads', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'viewer');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  await test.step('expect: {action_absent: create}', async () => {
    await app.expectActionAbsent('create');
  });
  await test.step('open_item: {where: {title: Review the plan}}', async () => {
    await app.openItem({ where: { title: 'Review the plan' } });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, action_absent: delete, field_readonly: report}', async () => {
    await app.expectScreen('task-card');
    await app.expectActionAbsent('delete');
    await app.expectFieldReadonly('report');
  });
});
